select p.proname,pg_get_function_identity_arguments(p.oid),p.prosecdef,p.proconfig,has_function_privilege(0,p.oid,'execute') public_execute,has_function_privilege('anon',p.oid,'execute') anon_execute,has_function_privilege('authenticated',p.oid,'execute') authenticated_execute,has_function_privilege('service_role',p.oid,'execute') service_execute from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('start_openingfit_mission_training_session','record_openingfit_mission_training_attempt') order by 1,2;
select case when to_regclass('public.openingfit_mission_training_sessions') is null then 'stage_absent' when to_regclass('public.openingfit_mission_training_sessions') is not null and (select relrowsecurity from pg_class where oid=to_regclass('public.openingfit_mission_training_sessions')) and exists(select 1 from pg_constraint where conrelid=to_regclass('public.openingfit_mission_training_attempts') and conname='openingfit_attempt_session_owner_fk') and exists(select 1 from pg_policies where schemaname='public' and tablename='openingfit_mission_training_sessions' and policyname='openingfit_mission_training_sessions_select_own' and cmd='SELECT' and roles=array['authenticated']::name[]) and exists(select 1 from pg_trigger where tgrelid=to_regclass('public.openingfit_mission_training_sessions') and tgname='openingfit_protect_training_session' and not tgisinternal) and not has_table_privilege(0,'public.openingfit_mission_training_sessions','select,insert,update,delete') and not has_table_privilege('anon','public.openingfit_mission_training_sessions','select,insert,update,delete') and has_table_privilege('authenticated','public.openingfit_mission_training_sessions','select') and not has_table_privilege('authenticated','public.openingfit_mission_training_sessions','insert,update,delete') and has_table_privilege('service_role','public.openingfit_mission_training_sessions','select,insert,update') and not has_table_privilege('service_role','public.openingfit_mission_training_sessions','delete,truncate,references,trigger') and (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['start_openingfit_mission_training_session','record_openingfit_mission_training_attempt']))=2 and exists(select 1 from pg_proc where oid=to_regprocedure('public.start_openingfit_mission_training_session(uuid,uuid,text,text,jsonb,integer,integer)') and prorettype=to_regtype('jsonb') and prosecdef and proconfig @> array['search_path=public']) and exists(select 1 from pg_proc where oid=to_regprocedure('public.record_openingfit_mission_training_attempt(uuid,uuid,uuid,text,text,text,text,integer,integer,timestamptz,jsonb)') and prorettype=to_regtype('public.openingfit_mission_training_attempts') and prosecdef and proconfig @> array['search_path=public']) and not exists(select 1 from (values(0::oid),('anon'::regrole::oid),('authenticated'::regrole::oid),('service_role'::regrole::oid)) r(oid) cross join (values(to_regprocedure('public.start_openingfit_mission_training_session(uuid,uuid,text,text,jsonb,integer,integer)')), (to_regprocedure('public.record_openingfit_mission_training_attempt(uuid,uuid,uuid,text,text,text,text,integer,integer,timestamptz,jsonb)'))) f(oid) where has_function_privilege(r.oid,f.oid,'execute')) and to_regprocedure('public.complete_openingfit_mission_training_session(uuid,uuid,uuid,text)') is null and public.openingfit_missions_schema_readiness() is not distinct from jsonb_build_object('ready',true,'schemaVersion',1) then 'stage_complete' else 'stage_partial' end classification;
